def find_lexicographically_smallest_good_permutation(n):
    if n == 2:
        return [2, 1]
    else:
        p = list(range(1, n + 1))
        for i in range(n - 1, 0, -1):
            if p[i] == i + 1:
                continue
            else:
                p[i], p[i - 1] = p[i - 1], p[i]
                break
        return p

def main():
    T = int(input().strip())
    results = []
    for _ in range(T):
        n = int(input().strip())
        results.append(find_lexicographically_smallest_good_permutation(n))
    for result in results:
        print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
